CREATE DATABASE IF NOT EXISTS campuscore_erp; USE campuscore_erp;
CREATE TABLE students (usn VARCHAR(20) PRIMARY KEY, name VARCHAR(120) NOT NULL, gender VARCHAR(20), dob DATE, blood_group VARCHAR(5), department VARCHAR(120), semester TINYINT, section VARCHAR(5), admission_year INT, email VARCHAR(120), phone VARCHAR(20), address TEXT, father_name VARCHAR(120), mother_name VARCHAR(120), parent_phone VARCHAR(20), parent_email VARCHAR(120), cgpa DECIMAL(3,2), previous_sgpa DECIMAL(3,2), backlogs TINYINT, username VARCHAR(60), password_hash VARCHAR(255));
CREATE TABLE predictions (id INT AUTO_INCREMENT PRIMARY KEY, student_usn VARCHAR(20), risk_level VARCHAR(15), pass_probability DECIMAL(5,2), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(student_usn) REFERENCES students(usn));
CREATE TABLE messages (id INT AUTO_INCREMENT PRIMARY KEY, recipient_usn VARCHAR(20), sender_name VARCHAR(120), subject VARCHAR(200), body TEXT, is_read BOOLEAN DEFAULT FALSE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE announcements (id INT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(200), body TEXT, scope VARCHAR(30), department VARCHAR(120), semester TINYINT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
